:0 0 0 1px rgba(255,255,255,.8)}.league-name{font-size:13px;font-weight:900}.kickoff{margin-left:auto;font-size:11px;font-weight:850;color:#e2fffb}.round{position:absolute;z-index:3;right:13px;top:43px;padding:5px 12px 5px 16px;border:1px solid var(--championship-hi);background:#101b25;color:#e8f5ff;font-size:9px;font-weight:950;letter-spacing:.06em;clip-path:polygon(9px 0,100% 0,100% calc(100% - 7px),calc(100% - 9px) 100%,0 100%,0 8px)}.content{padding:16px 12px 12px}.meta{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:9px;margin-bottom:11px}.meta span{font-size:11px;color:var(--muted);font-weight:750}.reads{display:flex;gap:5px;align-items:center;color:#47e6d1;font-weight:900}.reads i{display:inline-block;width:4px;height:12px;background:#47e6d1;border-radius:2px;box-shadow:6px -3px 0 #47e6d1,12px 2px 0 #47e6d1;margin-right:9px}.fixture{display:grid;grid-template-columns:1fr 42px;gap:8px;align-items:center}.teams{display:grid;gap:8px}.team{display:flex;align-items:center;gap:9px;min-width:0}.team-logo{width:27px;height:27px;border-radius:50%;background:#eef3f9;object-fit:contain;padding:2px;border:1px solid rgba(255,255,255,.65)}.fallback{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#274359;color:white;font-size:8px;font-weight:900}.team-name{font-size:15px;font-weight:860;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.open{height:42px;width:42px;border:1px solid var(--accent);border-radius:50%;display:grid;place-items:center;color:#73c2f5;font-size:29px;line-height:1;padding-bottom:3px}.signals{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.signal{border:1px solid #2e6548;background:#133726;color:#72e994;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:850}.signal.negative{border-color:#744148;background:#3a2027;color:#ff7681}.signal.ranking{border-color:#53457d;background:#2b2446;color:#b79cff}.summary{margin:10px 0 0;font-size:12px;line-height:1.35;color:#c3cfda;font-weight:650}.summary strong{color:#f3f7fb}.caption{margin:17px 7px 0;color:#8fa1b1;font-size:11px;line-height:1.45}.caption b{color:#52e6d6}@media(min-width:720px){.viewport{margin-top:32px;border:1px solid #203341;border-radius:28px;box-shadow:0 24px 60px rgba(0,0,0,.35)}}
